import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { chatAPI, documentsAPI } from "../services/api";

const Chat = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [docStatus, setDocStatus] = useState(null);
  const messagesEndRef = useRef(null);

  const statusLabel = docStatus?.has_documents
    ? `${docStatus.files_count} document${
        docStatus.files_count !== 1 ? "s" : ""
      } indexed`
    : docStatus?.folder_count > 0
    ? `${docStatus.folder_count} file${
        docStatus.folder_count !== 1 ? "s" : ""
      } found`
    : docStatus
    ? "No documents yet"
    : "Checking documents...";
  const statusTone = docStatus?.has_documents
    ? "bg-emerald-50 text-emerald-700 border-emerald-200"
    : docStatus?.folder_count > 0
    ? "bg-amber-50 text-amber-800 border-amber-200"
    : "bg-slate-50 text-slate-600 border-slate-200";
  const statusIcon = docStatus?.has_documents
    ? "✅"
    : docStatus?.folder_count > 0
    ? "⚠️"
    : "📂";
  const canReload =
    docStatus && !docStatus.has_documents && docStatus.folder_count > 0;
  const userInitial = user?.username?.[0]?.toUpperCase() || "U";

  useEffect(() => {
    loadDocumentStatus();
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const loadDocumentStatus = async () => {
    try {
      const statusResponse = await documentsAPI.status();
      console.log("📊 Document Status:", statusResponse.data);
      setDocStatus(statusResponse.data);
    } catch (error) {
      console.error("❌ Error loading document status:", error);
      // Set default status on error
      setDocStatus({
        has_documents: false,
        folder_count: 0,
        files_count: 0,
      });
    }
  };

  const handleReloadDocuments = async () => {
    try {
      setLoading(true);
      await documentsAPI.reload(false);
      await loadDocumentStatus();
      const successMsg = {
        id: Date.now(),
        type: "system",
        content: "✅ Documents reloaded successfully!",
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, successMsg]);
    } catch (error) {
      const errorMsg = {
        id: Date.now(),
        type: "error",
        content:
          error.response?.data?.detail ||
          "Failed to reload documents. Please try again.",
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, errorMsg]);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  const handleSend = async (e) => {
    e.preventDefault();
    if (!input.trim() || loading) return;

    const userMessage = {
      id: Date.now(),
      type: "user",
      content: input.trim(),
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput("");
    setLoading(true);

    try {
      const response = await chatAPI.query({ query: input.trim() });
      const botMessage = {
        id: Date.now() + 1,
        type: "bot",
        content: response.data.answer,
        citations: response.data.citations,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, botMessage]);
    } catch (error) {
      const errorMessage = {
        id: Date.now() + 1,
        type: "error",
        content:
          error.response?.data?.detail ||
          "Failed to get response. Please try again.",
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, errorMessage]);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend(e);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#f7f7f8] text-slate-900">
      {/* Header */}
      <header className="bg-white/80 border-b border-slate-200 backdrop-blur sticky top-0 z-10">
        <div className="max-w-5xl mx-auto px-4 sm:px-6">
          <div className="flex flex-wrap gap-4 justify-between items-center py-3">
            <div className="flex items-center space-x-3">
              <div className="w-9 h-9 bg-slate-900 rounded-lg flex items-center justify-center shadow-sm">
                <svg
                  className="w-5 h-5 text-white"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"
                  />
                </svg>
              </div>
              <div className="space-y-0.5">
                <h1 className="text-sm font-semibold text-slate-900 tracking-tight">
                  Sahakari Bot
                </h1>
                <div className="flex items-center gap-2 text-[11px] text-slate-500">
                  <span
                    className={`inline-flex items-center gap-1.5 px-2 py-0.5 border rounded-full ${statusTone}`}
                  >
                    <span>{statusIcon}</span>
                    {statusLabel}
                  </span>
                  <span className="hidden sm:inline">Compliance assistant</span>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {canReload && (
                <button
                  onClick={handleReloadDocuments}
                  disabled={loading}
                  className="px-3 py-1.5 text-xs font-medium text-slate-700 bg-slate-100 rounded-lg hover:bg-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500 transition disabled:opacity-50"
                  title="Reload documents from folder"
                >
                  Reload
                </button>
              )}
              <div className="hidden sm:flex items-center gap-2 bg-white border border-slate-200 rounded-full px-3 py-1.5">
                <span className="w-7 h-7 rounded-full bg-slate-900 text-white text-xs flex items-center justify-center">
                  {userInitial}
                </span>
                <span className="text-sm text-slate-700">{user?.username}</span>
              </div>
              <button
                onClick={handleLogout}
                className="px-3 py-1.5 text-xs font-medium text-slate-600 hover:text-slate-900 border border-slate-200 rounded-lg bg-white transition"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto px-4 sm:px-6 py-6">
        <div className="max-w-3xl w-full mx-auto">
          {messages.length === 0 ? (
            <div className="text-center mt-10 sm:mt-16">
              <div className="inline-flex items-center justify-center w-16 h-16 bg-white rounded-2xl mb-6 shadow-sm border border-slate-200">
                <svg
                  className="w-8 h-8 text-slate-900"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z"
                  />
                </svg>
              </div>
              <h2 className="text-2xl sm:text-3xl font-semibold text-slate-900 mb-3">
                How can I help you today?
              </h2>
              <p className="text-slate-600 mb-8 max-w-xl mx-auto">
                Ask about cybersecurity compliance, regulations, or risk
                management. Answers are grounded in your document library.
              </p>
              {!docStatus?.has_documents && (
                <div className="max-w-xl mx-auto bg-white border border-slate-200 rounded-2xl p-4 mb-6 text-left shadow-sm">
                  {docStatus?.folder_count > 0 ? (
                    <div>
                      <p className="text-sm text-slate-700 mb-2">
                        ⚠️ Found {docStatus.folder_count} file
                        {docStatus.folder_count !== 1 ? "s" : ""} in your
                        folder, but they are not processed yet.
                      </p>
                      <button
                        onClick={handleReloadDocuments}
                        disabled={loading}
                        className="text-xs px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-800 rounded-full font-medium transition disabled:opacity-50"
                      >
                        {loading ? "Processing..." : "Process documents"}
                      </button>
                    </div>
                  ) : (
                    <p className="text-sm text-slate-700">
                      ⚠️ No documents found. Add files to{" "}
                      <code className="bg-slate-100 px-1 rounded">
                        data/documents/
                      </code>{" "}
                      folder and restart the server or click reload.
                    </p>
                  )}
                </div>
              )}
              <div className="grid gap-3 sm:grid-cols-3 max-w-3xl mx-auto text-left">
                {[
                  "What are the password requirements?",
                  "How should we handle insider threats?",
                  "What are the data protection guidelines?",
                ].map((prompt) => (
                  <div
                    key={prompt}
                    className="bg-white border border-slate-200 rounded-2xl p-4 text-sm text-slate-700 shadow-sm"
                  >
                    {prompt}
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="space-y-0 pb-6">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`border-b border-slate-200 ${
                    msg.type === "user" ? "bg-[#f7f7f8]" : "bg-white"
                  }`}
                >
                  <div className="max-w-3xl mx-auto px-4 sm:px-6 py-6 flex items-start gap-4">
                    <div
                      className={`w-9 h-9 rounded-full flex items-center justify-center text-xs font-semibold ${
                        msg.type === "user"
                          ? "bg-blue-600 text-white"
                          : msg.type === "error"
                          ? "bg-red-100 text-red-700"
                          : "bg-slate-900 text-white"
                      }`}
                    >
                      {msg.type === "user"
                        ? userInitial
                        : msg.type === "error"
                        ? "!"
                        : "SB"}
                    </div>
                    <div className="flex-1">
                      <div className="text-xs font-semibold text-slate-600 mb-2">
                        {msg.type === "user"
                          ? "You"
                          : msg.type === "error"
                          ? "System"
                          : "Sahakari Bot"}
                      </div>
                      <p className="whitespace-pre-wrap leading-relaxed text-sm sm:text-base text-slate-900">
                        {msg.content}
                      </p>
                      {msg.citations && msg.citations.length > 0 && (
                        <div className="mt-4 pt-3 border-t border-slate-200 border-opacity-60">
                          <p className="text-xs font-semibold text-slate-600 mb-2 flex items-center">
                            <svg
                              className="w-4 h-4 mr-1"
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                              />
                            </svg>
                            Sources ({msg.citations.length})
                          </p>
                          <div className="space-y-1.5">
                            {msg.citations.map((citation, idx) => (
                              <div
                                key={idx}
                                className="text-xs text-slate-600 bg-slate-50 rounded-lg px-2 py-1.5"
                              >
                                <span className="font-medium">
                                  📄 {citation.source}
                                </span>
                                {citation.page && (
                                  <span className="text-slate-400">
                                    {" "}
                                    • Page {citation.page}
                                  </span>
                                )}
                                {citation.relevance_score && (
                                  <span className="text-slate-400">
                                    {" "}
                                    • Relevance:{" "}
                                    {(citation.relevance_score * 100).toFixed(
                                      0
                                    )}
                                    %
                                  </span>
                                )}
                              </div>
                            ))}
                          </div>
                        </div>
                      )}
                      <p className="text-xs mt-2 text-slate-400">
                        {new Date(msg.timestamp).toLocaleTimeString()}
                      </p>
                    </div>
                  </div>
                </div>
              ))}
              {loading && (
                <div className="border-b border-slate-200 bg-white">
                  <div className="max-w-3xl mx-auto px-4 sm:px-6 py-6 flex items-center gap-4">
                    <div className="w-9 h-9 rounded-full bg-slate-900 text-white text-xs font-semibold flex items-center justify-center">
                      SB
                    </div>
                    <div className="flex items-center space-x-2">
                      <div className="w-2 h-2 bg-slate-600 rounded-full animate-bounce"></div>
                      <div
                        className="w-2 h-2 bg-slate-600 rounded-full animate-bounce"
                        style={{ animationDelay: "0.1s" }}
                      ></div>
                      <div
                        className="w-2 h-2 bg-slate-600 rounded-full animate-bounce"
                        style={{ animationDelay: "0.2s" }}
                      ></div>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>
      </div>

      {/* Input Area */}
      <div className="bg-[#f7f7f8] border-t border-slate-200">
        <div className="max-w-3xl mx-auto px-4 sm:px-6 py-4">
          <form
            onSubmit={handleSend}
            className="bg-white border border-slate-200 rounded-2xl shadow-sm p-2 flex items-end gap-2"
          >
            <textarea
              rows={1}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder="Message Sahakari Bot..."
              className="flex-1 px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 focus:outline-none resize-none"
              disabled={loading}
            />
            <button
              type="submit"
              disabled={loading || !input.trim()}
              className="px-4 py-2 text-sm font-medium text-white bg-slate-900 rounded-xl hover:bg-slate-800 focus:outline-none focus:ring-2 focus:ring-slate-900 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition"
            >
              {loading ? (
                <svg
                  className="w-5 h-5 animate-spin"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  ></circle>
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  ></path>
                </svg>
              ) : (
                "Send"
              )}
            </button>
          </form>
          <p className="text-[11px] text-slate-500 mt-3 text-center">
            Sahakari Bot can make mistakes. Verify critical information.
          </p>
        </div>
      </div>
    </div>
  );
};

export default Chat;
